def read_subjects(rec):
    subjects = defaultdict(lambda: defaultdict(int))

    def _process_600(field, subjects):
        name_parts = []
        for k, v in field.get_subfields(['"'"'a'"'"', '"'"'b'"'"', '"'"'c'"'"']):
            v = v.strip('"'"' /,:'"'"')
            if k == '"'"'a'"'"':
                if m := re_flip_name.match(v):
                    v = flip_name(v)
            name_parts.append(v)
        for k, v in field.get_subfields(['"'"'d'"'"']):
            if k == '"'"'d'"'"':
                v = remove_trailing_dot(v.strip('"'"'.() '"'"'))
                if v:
                    name_parts.append(f"({v})")
        name = remove_trailing_dot('"'"' '"'"'.join(name_parts)).strip()
        if name:
            subjects['"'"'person'"'"'][name] += 1


    def _process_610(field, subjects):
        name_parts = []
        for k, v in field.get_subfields(['"'"'a'"'"', '"'"'b'"'"', '"'"'c'"'"', '"'"'d'"'"']):
            v = remove_trailing_dot(v.strip('"'"' /,;:'"'"')).strip()
            if v:
                name_parts.append(v)
        name = '"'"' '"'"'.join(name_parts).strip()
        if name:
            subjects['"'"'org'"'"'][name] += 1

    def _process_611(field, subjects):
        name_parts = []
        # Exclude subfields v, x, y, z as per requirements
        for k, v in field.get_all_subfields():
            if k not in '"'"'vxyz'"'"':
                v = remove_trailing_dot(v.strip('"'"' /,;:'"'"')).strip()
                if v:
                    name_parts.append(v)
        name = '"'"' '"'"'.join(name_parts).strip()
        if name:
            subjects['"'"'event'"'"'][name] += 1

    def _process_630(field, subjects):
        for v in field.get_subfield_values(['"'"'a'"'"']):
            v = remove_trailing_dot(v.strip()).strip()
            if v:
                subjects['"'"'work'"'"'][v] += 1

    def _process_650(field, subjects):
        for v in field.get_subfield_values(['"'"'a'"'"']):
            v = remove_trailing_dot(v.strip()).strip()
            if v:
                subjects['"'"'subject'"'"'][v] += 1

    def _process_651(field, subjects):
        for v in field.get_subfield_values(['"'"'a'"'"']):
            v = remove_trailing_dot(v.strip()).strip()
            if v:
                subjects['"'"'place'"'"'][flip_place(v)] += 1


    def _process_subfields_vxyz(field, subjects):
        for k, v in field.get_subfields(['"'"'v'"'"', '"'"'x'"'"', '"'"'y'"'"', '"'"'z'"'"']):
            v = remove_trailing_dot(v.strip()).strip()
            if not v:
                continue
            if k == '"'"'y'"'"':
                subjects['"'"'time'"'"'][v] += 1
            elif k == '"'"'z'"'"':
                subjects['"'"'place'"'"'][flip_place(v)] += 1
            elif k in ('"'"'v'"'"', '"'"'x'"'"'):
                subjects['"'"'subject'"'"'][v] += 1
    for tag, field in rec.read_fields(subject_fields):
        if tag == '"'"'600'"'"':
            _process_600(field, subjects)
        elif tag == '"'"'610'"'"':
            _process_610(field, subjects)
        elif tag == '"'"'611'"'"':
            _process_611(field, subjects)
        elif tag == '"'"'630'"'"':
            _process_630(field, subjects)
        elif tag == '"'"'650'"'"':
            _process_650(field, subjects)
        elif tag == '"'"'651'"'"':
            _process_651(field, subjects)

        _process_subfields_vxyz(field, subjects)

